1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Relay Pricing</title>
7	<style>
8	  * { box-sizing: border-box }
9	  body { margin: 0; font-family: system-ui, sans-serif; background: #ffffff; color: #24292f }
10	  header { padding: 20px 32px; border-bottom: 1px solid #e8eaee; font-weight: 700 }
11	  main { max-width: 720px; margin: 40px auto; padding: 0 24px }
12	  h1 { font-size: 28px; margin: 0 0 6px }
13	  p.sub { color: #6a737a; margin: 0 0 32px; font-size: 15px; line-height: 1.6 }
14	  .card { border: 1px solid #e8eaee; border-radius: 12px; padding: 28px; max-width: 380px }
15	  .plan { font-size: 13px; letter-spacing: 0.08em; text-transform: uppercase; color: #6a737a }
16	  .price { font-size: 34px; font-weight: 700; margin: 10px 0 }
17	  .price small { font-size: 14px; font-weight: 400; color: #6a737a }
18	  ul { padding-left: 18px; margin: 0 0 24px; color: #6a737a; font-size: 14px; line-height: 1.9 }
19	  a.more { color: #4f6bbd; font-size: 14px }
20	  a.more:focus-visible { outline: 2px solid #4f6bbd; outline-offset: 2px }
21	  button { width: 100%; padding: 12px; background: #2b5cb5; color: #ffffff; border: 0; border-radius: 8px; font-size: 15px; font-weight: 600; cursor: pointer; margin-bottom: 14px }
22	  button:focus-visible { outline: 2px solid #2b5cb5; outline-offset: 2px }
23	  .note { font-size: 12px; color: #6a737a; margin-top: 20px }
24	</style>
25	<script>
26	  window.__activated = []
27	  document.addEventListener('click', function (e) {
28	    var hit = e.target instanceof Element ? e.target.closest('[data-track]') : null
29	    var name = hit ? hit.getAttribute('data-track') : null
30	    if (name) window.__activated.push(name)
31	  })
32	</script>
33	</head>
34	<body>
35	<header>Relay</header>
36	<main>
37	  <h1>Simple pricing</h1>
38	  <p class="sub">One plan, every feature, cancel whenever you like. No usage tiers and no per-seat surprises at the end of the month.</p>
39	  <div class="card">
40	    <div class="plan">Team</div>
41	    <div class="price">$24 <small>per member, per month</small></div>
42	    <ul>
43	      <li>Unlimited shared inboxes</li>
44	      <li>Automations and scheduled sends</li>
45	      <li>Priority support within one business day</li>
46	    </ul>
47	    <button type="button" data-track="cta">Start free trial</button>
48	    <a class="more" href="#details" data-track="learn-more">See what is included</a>
49	  </div>
50	  <p class="note" id="details">Prices exclude VAT. Annual billing saves two months.</p>
51	</main>
52	</body>
53	</html>
